import React, { useState } from 'react';

const SENTIMENT_COLOR = {
  positive: { bg: '#3ecf8e20', text: '#3ecf8e', dot: '#3ecf8e' },
  negative: { bg: '#f0606020', text: '#f06060', dot: '#f06060' },
  neutral:  { bg: '#7a7a9a20', text: '#9090b0', dot: '#7a7a9a' },
};

const SENTIMENT_EMOJI = { positive: '📈', negative: '📉', neutral: '➖' };

function timeAgo(dateStr) {
  if (!dateStr) return '';
  const diff = Date.now() - new Date(dateStr).getTime();
  const hours = Math.floor(diff / 3600000);
  if (hours < 1) return 'Just now';
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  return `${days}d ago`;
}

export default function ArticleCard({ article, index }) {
  const [insightsOpen, setInsightsOpen] = useState(false);
  const s = SENTIMENT_COLOR[article.sentiment] || SENTIMENT_COLOR.neutral;

  return (
    <div
      className="fade-in"
      style={{
        animationDelay: `${index * 0.05}s`,
        background: '#12121a',
        border: '1px solid #2a2a3a',
        borderRadius: 12,
        overflow: 'hidden',
        display: 'flex',
        flexDirection: 'column',
        transition: 'border-color 0.2s, transform 0.2s',
      }}
      onMouseEnter={e => {
        e.currentTarget.style.borderColor = '#f5c84250';
        e.currentTarget.style.transform = 'translateY(-2px)';
      }}
      onMouseLeave={e => {
        e.currentTarget.style.borderColor = '#2a2a3a';
        e.currentTarget.style.transform = 'translateY(0)';
      }}
    >
      {/* Image */}
      {article.image_url && (
        <img
          src={article.image_url}
          alt=""
          style={{ width: '100%', height: 160, objectFit: 'cover' }}
          onError={e => { e.target.style.display = 'none'; }}
        />
      )}

      <div style={{ padding: '18px 20px', display: 'flex', flexDirection: 'column', gap: 12, flex: 1 }}>

        {/* Meta row */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span style={{
            fontSize: 11, fontWeight: 600, textTransform: 'uppercase',
            letterSpacing: 1, color: '#f5c842'
          }}>
            {article.category}
          </span>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <span style={{ fontSize: 11, color: '#5a5a7a' }}>{timeAgo(article.published_at)}</span>
            {/* Sentiment badge */}
            <span style={{
              display: 'inline-flex', alignItems: 'center', gap: 4,
              background: s.bg, color: s.text,
              padding: '2px 10px', borderRadius: 99,
              fontSize: 11, fontWeight: 600
            }}>
              <span style={{
                width: 5, height: 5, borderRadius: '50%',
                background: s.dot, display: 'inline-block'
              }} />
              {SENTIMENT_EMOJI[article.sentiment]} {article.sentiment}
            </span>
          </div>
        </div>

        {/* Title */}
        <a
          href={article.url}
          target="_blank"
          rel="noreferrer"
          style={{ color: '#f0f0f8', fontFamily: 'Playfair Display, serif', fontSize: 17, lineHeight: 1.4, fontWeight: 700 }}
          onMouseEnter={e => e.target.style.color = '#f5c842'}
          onMouseLeave={e => e.target.style.color = '#f0f0f8'}
        >
          {article.title}
        </a>

        {/* Source */}
        <span style={{ fontSize: 12, color: '#5a5a7a' }}>{article.source_name}</span>

        {/* AI Summary */}
        {article.summary && (
          <div style={{
            background: '#1a1a2a', borderLeft: '2px solid #f5c842',
            borderRadius: '0 8px 8px 0', padding: '10px 14px'
          }}>
            <div style={{ fontSize: 10, textTransform: 'uppercase', letterSpacing: 1.5, color: '#f5c842', marginBottom: 4 }}>
              AI Summary
            </div>
            <p style={{ fontSize: 13, color: '#c0c0d8', lineHeight: 1.6, margin: 0 }}>
              {article.summary}
            </p>
          </div>
        )}

        {/* Key insights toggle */}
        {article.key_insights?.length > 0 && (
          <div>
            <button
              onClick={() => setInsightsOpen(v => !v)}
              style={{
                background: 'none', border: '1px solid #2a2a3a',
                borderRadius: 8, padding: '5px 14px',
                color: '#9090b0', fontSize: 12, fontWeight: 500,
                transition: 'all 0.15s',
              }}
              onMouseEnter={e => { e.target.style.borderColor = '#f5c842'; e.target.style.color = '#f5c842'; }}
              onMouseLeave={e => { e.target.style.borderColor = '#2a2a3a'; e.target.style.color = '#9090b0'; }}
            >
              {insightsOpen ? '▲ Hide' : '▼ Key Insights'} ({article.key_insights.length})
            </button>

            {insightsOpen && (
              <ul style={{ margin: '10px 0 0 0', paddingLeft: 0, listStyle: 'none', display: 'flex', flexDirection: 'column', gap: 6 }}>
                {article.key_insights.map((insight, i) => (
                  <li key={i} style={{
                    display: 'flex', alignItems: 'flex-start', gap: 8,
                    fontSize: 13, color: '#9090b0', lineHeight: 1.5
                  }}>
                    <span style={{ color: '#f5c842', marginTop: 2, flexShrink: 0 }}>›</span>
                    {insight}
                  </li>
                ))}
              </ul>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
